source_text:
\spheader 226Yd Suppose that $a<b$ in $\Bbb R$, and that
$F:[a,b]\to\Bbb R$ is a function of bounded variation;  let $F_p$ be its saltus part.   Show that
$|F(b)-F(a)|\le\mu F[\,[a,b]\,]+\Var_{[a,b]}F_p$, where $\mu$ is Lebesgue measure on $\Bbb R$.
%226C
}%end of exercises


\endnotes{

target_text:
\spheader 226Yd Andaikan $a<b$ dalam $\Bbb R$, dan
$F:[a,b]\to\Bbb R$ suatu fungsi bervariasi terbatas;  misalkan $F_p$ bagian saltusnya.   Tunjukkan bahwa
$|F(b)-F(a)|\le\mu F[\,[a,b]\,]+\Var_{[a,b]}F_p$, dengan $\mu$ ukuran Lebesgue pada $\Bbb R$.
%226C
}%end of exercises


\endnotes{
